# Define a function that loads the 'fft_factorize' function from the GSL library.
def load_fft_factorize(gsl):
    return gsl.gsl_fft_factorize

# Define a function to compute prime factorization using the specified subtransforms array.
def prime_factors(n, subtransforms):
    result = [0] * (n + 1)
    for i in range(len(subtransforms)):
        if subtransforms[i][0] > n // 2 ** len(subtransforms[:i+1]):
            break
    for i in range(i, -1, -1):
        while n % subtransforms[i][0] == 0:
            result[n//subtransforms[i][0]] += 1
            n //= subtransforms[i][0]
    return result, len(result) - 1

# Define a function that uses the 'fft_factorize' function to compute prime factorization.
def fft_factorize(n, subtransforms):
    c_gsl_fft_factorize = load_fft_factorize(gsl)
    factors = array('i', [0] * (n + 1))
    num_factors = c_gsl_fft_factorize(n, factors)
    return factors.tolist(), num_factors

