from ctypes import c_double, POINTER

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols

    @staticmethod
    def alloc(rows, cols):
        return ctypes.POINTER(ctypes.c_double) * (rows * cols)

    @staticmethod
    def free(matrix):
        del matrix[:]

    @staticmethod
    def to_gsl_matrix(np_array):
        rows = np_array.shape[0]
        cols = np_array.shape[1]
        gsl_matrix = GSLMatrix.alloc(rows, cols)
        for i in range(rows):
            for j in range(cols):
                gsl_matrix[i * cols + j].value = np_array[i, j]
        return gsl_matrix

    @staticmethod
    def to_numpy(gsl_matrix, rows, cols):
        np_array = np.zeros((rows, cols))
        for i in range(rows):
            for j in range(cols):
                np_array[i, j] = gsl_matrix[i * cols + j].value
        return np_array

def numpy_to_gsl_matrix(np_array):
    rows = np_array.shape[0]
    cols = np_array.shape[1]
    gsl_matrix = GSLMatrix.alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl_matrix[i * cols + j].value = np_array[i, j]
    return gsl_matrix

