class GslRstatQuantileWorkspace:
    def __init__(self):
        self.workspace = None
        self.handle = ctypes.c_void_p()

    def allocate(self) -> None:
        self.workspace = gsl.rstat_quantile_alloc()
        self.handle = self.workspace

    def reset(self) -> None:
        if self.handle:
            gsl.rstat_quantile_reset(self.workspace)
        else:
            raise ValueError("Workspace not allocated")

    def add(self, values: List[float]) -> None:
        if self.handle:
            data_array = np.array(values, dtype=np.float64)
            ctypes_pointer = data_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
            gsl.rstat_quantile_add(self.workspace, len(values), ctypes_pointer)
        else:
            raise ValueError("Workspace not allocated")

    def get(self, p: float) -> float:
        if self.handle:
            return gsl.rstat_quantile_get(self.workspace, p)
        else:
            raise ValueError("Workspace not allocated")

    def free(self) -> None:
        if self.handle:
            gsl.rstat_quantile_free(self.workspace)
            self.handle = ctypes.c_void_p()
        else:
            raise ValueError("Workspace not allocated")

def compute_quantile(p: float, values: List[float]) -> float:
    workspace = GslRstatQuantileWorkspace()
    workspace.allocate()
    try:
        workspace.add(values)
        result = workspace.get(p)
    finally:
        if workspace.handle:
            workspace.free()
    return result

